examples:
TypeScript example: 
try {
  await client.generate('hello')
} catch (e) {
  if (e instanceof RateLimitError && e.retriable) {
    setTimeout(() => retry(), e.backoff_hint_ms || 100)
  }
}

Go example: 
resp, err := client.Generate(ctx, req)
if err != nil {
  if se, ok := errors.AsStreamError(err); ok && se.Retriable() {
    // use se.RetryAfter or se.BackoffHintMs()
  }
}
